"use strict";(globalThis.webpackChunkmy_website||=[]).push([[94354],{4740(e){e.exports=JSON.parse('{"slug":"governance-action","title":"Governance Action","short":"A formal proposal submitted on-chain for the Cardano community to vote on.","category":"governance","aliases":["Governance Proposal","Governance Action Proposal","Proposal Procedure"],"mentalModel":"A motion submitted to the network\'s parliament. Anyone can post one, and DReps, stake pool operators, and the Constitutional Committee vote on it (which bodies are required depends on the action type); if it passes, the action it describes (a treasury spend, a parameter change, a constitutional amendment) is enacted directly by the protocol.","related":["drep","constitutional-committee","cip-1694","treasury","governance-action-lifetime","voting-thresholds"],"sources":[],"link":"/governance","level":"intermediate","body":"A formal proposal submitted on-chain for the Cardano community to vote on. Types include treasury withdrawals, protocol parameter changes, and constitutional amendments. See [Governance Actions](https://developers.cardano.org/docs/governance/cardano-governance/governance-actions) for details."}')}}]);